import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { DynamicBorder, getSelectListTheme } from "@earendil-works/pi-coding-agent";
import { Container, type SelectItem, SelectList, Text } from "@earendil-works/pi-tui";

export default function (pi: ExtensionAPI) {
	pi.registerCommand("menu", {
		description: "Open a drinks menu",
		handler: async (_args, ctx) => {
			const items: SelectItem[] = [
				{ value: "tea", label: "Tea", description: "Hot" },
				{ value: "juice", label: "Juice", description: "Cold" },
				{ value: "water", label: "Water" },
			];
			const choice = await ctx.ui.custom<string | null>((tui, theme, _kb, done) => {
				const container = new Container();
				container.addChild(new DynamicBorder((s: string) => theme.fg("accent", s)));
				container.addChild(new Text(theme.fg("accent", theme.bold("Drinks")), 1, 0));
				const list = new SelectList(items, 5, getSelectListTheme());
				list.onSelect = (item) => done(item.value);
				list.onCancel = () => done(null);
				container.addChild(list);
				container.addChild(new DynamicBorder((s: string) => theme.fg("accent", s)));
				return {
					render: (width: number) => container.render(width),
					invalidate: () => container.invalidate(),
					handleInput: (data: string) => {
						list.handleInput(data);
						tui.requestRender();
					},
				};
			});
			ctx.ui.notify(choice ? `Chose ${choice}` : "Menu closed", "info");
		},
	});
}

