import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Text } from "@earendil-works/pi-tui";

export default function (pi: ExtensionAPI) {
	pi.registerCommand("ui", {
		description: "Exercise the UI in RPC mode",
		handler: async (_args, ctx) => {
			ctx.ui.setStatus("build", "passing");
			ctx.ui.setStatus("build", undefined);
			ctx.ui.setWidget("todo", ["one", "two"], { placement: "belowEditor" });
			ctx.ui.setWidget("todo", undefined);
			ctx.ui.setWidget("component", () => new Text("ignored", 0, 0));
			ctx.ui.setTitle("ri test");
			ctx.ui.setEditorText("draft");
			ctx.ui.pasteToEditor("pasted");
			ctx.ui.setWorkingMessage("Thinking hard");
			const custom = await ctx.ui.custom(() => new Text("never", 0, 0));
			ctx.ui.notify(`custom: ${custom}, editor: ${JSON.stringify(ctx.ui.getEditorText())}, expanded: ${ctx.ui.getToolsExpanded()}`, "info");
		},
	});
}

